        : [base[0] + 1, 0, 0];
      return version => compareParts(version, base) >= 0 && compareParts(version, upper) < 0;
    }
    return version => {
      const order = compareParts(version, base);
      switch (operator) {
        case '': return order === 0;
        case '>=': return order >= 0;
        case '>': return order > 0;
        case '<=': return order <= 0;
        case '<': return order < 0;
        default: throw new TypeError('Invalid range');
      }
    };
  });
  return version => terms.every(term => term(version));
