'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies, compare } = require('./src/semver');

// Backtracking must undo constraints of a rejected choice.
const bt = {
  a: { '2.0.0': { b: '^2.0.0', c: '1.0.0' }, '1.0.0': { b: '^1.0.0' } },
  b: { '2.0.0': { c: '^2.0.0' }, '1.0.0': {} },
  c: { '1.0.0': {}, '2.0.0': {} },
};
assert.deepEqual(resolve(bt, { a: '*' }), { a: '1.0.0', b: '1.0.0' });

// Cycle terminates.
const cyc = { x: { '1.0.0': { y: '*' } }, y: { '1.0.0': { x: '1.0.0' } } };
assert.deepEqual(resolve(cyc, { x: '*' }), { x: '1.0.0', y: '1.0.0' });

// Long chain with many iterations (>4096) and no recursion.
const chain = {};
const N = 50000;
for (let i = 0; i < N; i++) chain['p' + i] = { '1.0.0': i + 1 < N ? { ['p' + (i + 1)]: '^1.0.0' } : {} };
assert.equal(Object.keys(resolve(chain, { p0: '*' })).length, N);

// Missing package unsatisfiable; conflict -> null.
assert.equal(resolve({}, { nope: '*' }), null);
assert.equal(resolve({ a: { '1.0.0': { a: '2.0.0' } } }, { a: '*' }), null);
assert.deepEqual(resolve({}, {}), {});

// First-found: earlier choice preferred highest even if later gets lower.
const ff = { a: { '2.0.0': { b: '<=1.0.0' }, '1.0.0': {} }, b: { '1.0.0': {}, '2.0.0': {} } };
assert.deepEqual(resolve(ff, { a: '*', b: '*' }), { a: '2.0.0', b: '1.0.0' });

// Semver caret.
assert.equal(satisfies('0.3.0', '^0.2.3'), false);
assert.equal(satisfies('0.2.9', '^0.2.3'), true);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('0.0.3', '^0.0.3'), true);
assert.equal(satisfies('1.9.0', '^1.2.0'), true);
assert.equal(compare('1.10.0', '1.9.0'), 1);

